<script setup lang="ts">
import RemoteTaskDetails from '../components/RemoteTaskDetails.vue';
import {computed,ref} from 'vue';import {ElMessage} from 'element-plus';import {usePlatform} from '../stores/platform';import {filterRows} from '../domain';import type {Report,Field} from '../domain';import QueryForm from '../components/QueryForm.vue';import DataTable from '../components/DataTable.vue';import ChartPanel from '../components/ChartPanel.vue';import RemoteReportPreview from '../components/RemoteReportPreview.vue';import {exportRows} from '../utils/files';import {apiMode,request} from '../api/client';import {timeRange} from '../api/gateway';
const taskDetail=ref('');const p=usePlatform(),preview=ref<Report|null>(null),visibleRows=ref<Record<string,unknown>[]>([]);
const scope=computed(()=>( {'参数配置':'configs','运维报表':'reports','运维通知':'notifications','操作日志':'logs','短信日志':'sms','任务中心':'tasks'} as Record<string,string>)[p.active]||'configs');
const fields=computed<Field[]>(()=>scope.value==='configs'?[{key:'group',label:'分组名称'},{key:'device',label:'设备名称'}]:scope.value==='reports'?[{key:'name',label:'任务名称'},{key:'start',label:'创建开始时间',type:'date'},{key:'end',label:'创建结束时间',type:'date'}]:scope.value==='notifications'?[{key:'name',label:'通知任务名称'}]:scope.value==='logs'?[{key:'name',label:'用户名'},{key:'start',label:'操作开始',type:'datetime-local'},{key:'end',label:'操作结束',type:'datetime-local'}]:scope.value==='sms'?[{key:'name',label:'任务名称'},{key:'recipient',label:'接收人员号码'},{key:'start',label:'发送开始',type:'datetime-local'},{key:'end',label:'发送结束',type:'datetime-local'}]:[{key:'name',label:'任务名称'}]);
const columns=computed(()=>scope.value==='configs'?[{key:'name',label:'任务名称',link:true},{key:'region',label:'区域'},{key:'group',label:'分组'},{key:'count',label:'设备数量'},{key:'status',label:'状态'}]:scope.value==='reports'?[{key:'name',label:'任务名称',link:true},{key:'subtype',label:'报表类型'},{key:'mode',label:'生成方式'},{key:'period',label:'统计周期'},{key:'date',label:'创建时间'}]:scope.value==='notifications'?[{key:'name',label:'任务名称',link:true},{key:'channel',label:'通知方式'},{key:'time',label:'通知时间'},{key:'recipient',label:'通知对象'},{key:'status',label:'状态'},{key:'last',label:'上次发送'}]:scope.value==='logs'?[{key:'user',label:'登录账号'},{key:'name',label:'用户名'},{key:'action',label:'操作事件'},{key:'time',label:'操作时间'}]:scope.value==='sms'?[{key:'name',label:'任务名称'},{key:'recipient',label:'接收人员号码'},{key:'time',label:'发送时间'},{key:'content',label:'消息内容'},{key:'status',label:'状态'}]:[{key:'name',label:'任务名称'},{key:'kind',label:'任务类型'},{key:'status',label:'状态'}]);
const ownLogs=computed(()=>apiMode==='http'||p.superuser?p.db.logs:p.db.logs.filter(l=>l.user===p.currentUser?.account));
const rows=computed(()=>{let source:Record<string,unknown>[]=[];if(scope.value==='configs')source=p.db.configs.map(c=>({...c,count:c.deviceIds.length,device:p.db.devices.filter(d=>c.deviceIds.includes(d.id)).map(d=>d.name).join(' ')}));if(scope.value==='reports')source=p.db.reports.map(r=>({...r,linkDisabled:r.mode!=='单报表'}));if(scope.value==='notifications')source=p.db.notifications;if(scope.value==='logs')source=ownLogs.value;if(scope.value==='sms')source=p.db.sms;if(scope.value==='tasks'&&apiMode==='http')source=p.remote.tasks.map(t=>({id:t.taskId,name:t.name,kind:t.taskType,status:t.status}));if(scope.value==='tasks'&&apiMode==='mock')source=[...Object.entries(p.db.analysis).flatMap(([kind,tasks])=>tasks.map(t=>({...t,kind}))),...p.db.configs.map(c=>({...c,kind:'参数配置'})),...p.db.reports.map(r=>({...r,kind:'运维报表'}))];return p.filterRows(source,p.f,{name:r=>r.name,group:r=>r.group,device:r=>r.device,recipient:r=>r.recipient,start:r=>r.time||r.date,end:r=>r.time||r.date});});
function open(row:Record<string,unknown>){if(scope.value==='configs'){const c=p.db.configs.find(c=>c.id===row.id);if(c){p.info('配置任务详情',[['任务名称',c.name],['场所区域',c.region],['设备分组',c.group],['设备',p.db.devices.filter(d=>c.deviceIds.includes(d.id)).map(d=>d.name).join('、')],['参数',c.params],['状态',c.status]]);p.modal.model={configId:c.id};}}if(scope.value==='reports'){const r=p.db.reports.find(r=>r.id===row.id);if(r?.mode==='单报表')preview.value=r;else p.info('多报表集合',[['下载方式','多报表需下载 ZIP，集合无单独预览。']]);}if(scope.value==='notifications'){p.info('通知任务详情',Object.entries(row));p.modal.model={notificationId:String(row.id)};}}
function add(){if(scope.value==='configs')p.formConfig();if(scope.value==='reports')p.formReport();if(scope.value==='notifications')p.formNotification();}
async function exportLog(){try{if(apiMode==='http'){if(scope.value==='logs'){const r=await request('exportAuditEvents',{body:{scope:'OWN_ALL',format:'XLSX',reason:'导出本人全部授权操作日志'}});ElMessage.success('导出任务已提交：'+r.data.taskId+'；完成后到任务中心下载');return;}const deliveryIds=visibleRows.value.map(row=>String(row.id));if(!deliveryIds.length)throw new Error('当前页没有可导出的短信日志');const r=await request('exportSmsLogs',{body:{search:{timeRange:timeRange(p.f),pageSize:p.remote.pageSize,sortBy:'sentAt',taskName:String(p.f.name||'')||undefined,recipientQuery:String(p.f.recipient||'')||undefined},format:'XLSX',reason:'导出当前页短信日志',scope:'SELECTED_PAGE',deliveryIds}});ElMessage.success('导出任务已提交：'+r.data.taskId+'；完成后到任务中心下载');return;}if(scope.value==='logs')await exportRows('操作日志',p.db.logs.filter(l=>l.user===p.currentUser?.account));else await exportRows('短信日志',visibleRows.value);p.log('导出日志');}catch(e){ElMessage.error(e instanceof Error?e.message:String(e));}}
const previewRows=computed(()=>preview.value?p.reportData(preview.value):[]),previewColumns=computed(()=>Object.keys(previewRows.value[0]||{结果:''}).map(k=>({key:k,label:k})));const previewChart=computed(()=>{if(!preview.value)return [];const r=preview.value,count=r.period==='年'?12:r.period==='月'?new Date(Number(r.date.slice(0,4)),Number(r.date.slice(5,7)),0).getDate():24;return Array.from({length:count},(_,i)=>{const at=r.period==='年'?r.date.slice(0,4)+'-'+String(i+1).padStart(2,'0'):r.period==='月'?r.date.slice(0,7)+'-'+String(i+1).padStart(2,'0'):r.date+' '+String(i).padStart(2,'0')+':00';return Object.fromEntries([['日期',at],...['示例移动','示例联通','示例电信'].map(op=>[op,previewRows.value.filter(row=>'运营商' in row&&row.运营商===op&&'时间' in row&&String(row.时间).startsWith(at.slice(0,r.period==='日'?13:10))).reduce((a,b)=>a+Number('数据量' in b?b.数据量:0),0)])]);});});
</script>
<template><QueryForm :fields="fields" :model="p.f" @search="p.query" @reset="p.reset"/><div v-if="['configs','reports','notifications'].includes(scope)" class="actions"><el-button type="primary" @click="add">新增</el-button><el-button v-if="scope==='notifications'" @click="p.revoke('notifications')">撤销通知</el-button><el-button @click="p.remove(scope as 'configs'|'reports'|'notifications')">删除</el-button></div><DataTable :rows="rows" :columns="columns" :title="p.active" @select="p.chosen=$event" @visible="visibleRows=$event" @open="open"><template #actions><el-button v-if="scope==='logs'||scope==='sms'" @click="exportLog">导出</el-button></template><template v-if="scope==='reports'||scope==='notifications'||scope==='tasks'" #rowActions="{row}"><el-button v-if="scope==='tasks'&&apiMode==='http'" size="small" link type="primary" @click="taskDetail=String(row.id)">任务详情 / 导入结果</el-button><el-button v-if="scope==='tasks'&&apiMode==='http'&&row.status==='SUCCESS'" size="small" link type="primary" @click="p.downloadTask(String(row.id))">下载任务结果</el-button><el-button v-if="scope==='reports'" size="small" link type="primary" @click="p.downloadReport(row as Report)">下载</el-button><el-button v-if="scope==='notifications'&&apiMode==='mock'" size="small" link type="primary" :disabled="row.status!=='执行中'" @click="p.simulateNotification(String(row.id))">模拟到达通知时间</el-button></template></DataTable><el-dialog :model-value="!!taskDetail" title="任务详情" width="1000px" @close="taskDetail=''"><RemoteTaskDetails v-if="taskDetail" :key="taskDetail" :task-id="taskDetail"/></el-dialog><el-dialog :model-value="!!preview" :title="'报表详情 · '+preview?.name" width="1000px" @close="preview=null"><RemoteReportPreview v-if="apiMode==='http'&&preview" :report-id="preview.id"/><template v-else-if="preview"><div class="section-head"><span>{{preview.subtype}} · {{preview.period}}报表</span><div class="spacer"/><el-button @click="p.downloadReport(preview)">下载</el-button></div><div class="report-metrics"><span>区域：{{preview.region}}</span><span>设备数量：{{p.db.devices.filter(d=>preview?.region==='全部'||d.region===preview?.region).length}}</span><span>数据总览：{{previewRows.length}} 条</span><span>数据总量：{{previewRows.reduce((a,b)=>a+Number('数据量' in b?b.数据量:0),0)}}</span><span>统计日期：{{preview.period==='年'?preview.date.slice(0,4):preview.period==='月'?preview.date.slice(0,7):preview.date}}</span></div><template v-if="preview.subtype?.includes('电围')"><ChartPanel :title="preview.subtype" :rows="previewChart" :labels="['示例移动','示例联通','示例电信']"/><p v-if="preview.subtype==='电围设备采集数据统计'">{{p.db.devices.filter(d=>preview?.region==='全部'||d.region===preview?.region).map(d=>d.name+' / '+d.serial+' / '+d.site).join('；')}}</p></template><DataTable :rows="previewRows.map((r,i)=>({...r,id:String(i)}))" :columns="previewColumns" :selectable="false"/></template></el-dialog></template>



